-- Default variables
-- Copy these to ~/.config/hypr/custom/variables.conf to make changes in a dotfiles-update-friendly manner

-- Apps
-- PULL REQUESTS ADDING MORE WILL NOT BE ACCEPTED, CONFIG FOR YOURSELF
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

-- The folder within ~/.config/quickshell containing the config
qsConfig = "ii"

terminal = "/usr/bin/bash /home/aarush/.config/hypr/hyprland/scripts/launch_first_available.sh \"kitty -1\" \"foot\" \"alacritty\" \"wezterm\" \"konsole\" \"kgx\" \"uxterm\" \"xterm\""
fileManager = "/usr/bin/bash /home/aarush/.config/hypr/hyprland/scripts/launch_first_available.sh \"dolphin\" \"nautilus\" \"nemo\" \"thunar\" \"kitty -1 fish -c yazi\""
browser = "/usr/bin/bash /home/aarush/.config/hypr/hyprland/scripts/launch_first_available.sh \"google-chrome-stable\" \"zen-browser\" \"firefox\" \"brave\" \"chromium\" \"microsoft-edge-stable\" \"opera\" \"librewolf\""
codeEditor = "/usr/bin/bash /home/aarush/.config/hypr/hyprland/scripts/launch_first_available.sh \"antigravity\" \"code\" \"codium\" \"cursor\" \"zed\" \"zedit\" \"zeditor\" \"kate\" \"gnome-text-editor\" \"emacs\" \"command -v nvim && kitty -1 nvim\" \"command -v micro && kitty -1 micro\""
officeSoftware = "/usr/bin/bash /home/aarush/.config/hypr/hyprland/scripts/launch_first_available.sh \"wps\" \"onlyoffice-desktopeditors\" \"libreoffice\""
textEditor = "/usr/bin/bash /home/aarush/.config/hypr/hyprland/scripts/launch_first_available.sh \"kate\" \"gnome-text-editor\" \"emacs\""
volumeMixer = "/usr/bin/bash /home/aarush/.config/hypr/hyprland/scripts/launch_first_available.sh \"pavucontrol-qt\" \"pavucontrol\""
settingsApp = "XDG_CURRENT_DESKTOP=gnome /usr/bin/bash /home/aarush/.config/hypr/hyprland/scripts/launch_first_available.sh \"qs -p ~/.config/quickshell/" .. qsConfig .. "/settings.qml\" \"systemsettings\" \"gnome-control-center\" \"better-control\""
taskManager = "/usr/bin/bash /home/aarush/.config/hypr/hyprland/scripts/launch_first_available.sh \"gnome-system-monitor\" \"plasma-systemmonitor --page-name Processes\" \"command -v btop && kitty -1 fish -c btop\""

dontLoadDefaultExecs = ""
dontLoadDefaultGeneral = ""
dontLoadDefaultRules = ""
dontLoadDefaultKeybinds = ""

return {
    terminal = terminal,
    fileManager = fileManager,
    browser = browser,
    codeEditor = codeEditor,
    officeSoftware = officeSoftware,
    textEditor = textEditor,
    volumeMixer = volumeMixer,
    settingsApp = settingsApp,
    taskManager = taskManager,
    qsConfig = qsConfig,
}
